import os
import subprocess
import typing

from apscheduler.events import (
    EVENT_JOB_ERROR,
    EVENT_JOB_EXECUTED,
    EVENT_JOB_SUBMITTED,
    JobEvent,
)
from apscheduler.schedulers.asyncio import AsyncIOScheduler
from apscheduler.util import undefined


class OlAsyncIOScheduler(AsyncIOScheduler):
    def __init__(self):
        super().__init__({'apscheduler.timezone': 'UTC'})
        self.add_listener(
            job_listener, EVENT_JOB_EXECUTED | EVENT_JOB_ERROR | EVENT_JOB_SUBMITTED
        )

    @typing.override
    def add_job(
        self,
        func,
        trigger=None,
        args=None,
        kwargs=None,
        id=None,
        name=None,
        misfire_grace_time=undefined,
        coalesce=undefined,
        max_instances=undefined,
        next_run_time=undefined,
        jobstore="default",
        executor="default",
        replace_existing=False,
        **trigger_args,
    ):
        return super().add_job(
            func,
            trigger,
            args,
            kwargs,
            # Give decorator-created jobs a predictable id.
            id if id is not None else func.__name__,
            name,
            misfire_grace_time,
            coalesce,
            max_instances,
            next_run_time,
            jobstore,
            executor,
            replace_existing,
            **trigger_args,
        )


def job_listener(event: JobEvent):
    if event.code == EVENT_JOB_SUBMITTED:
        print(f"[OL-MONITOR] Job {event.job_id} has started.", flush=True)
    elif event.code == EVENT_JOB_EXECUTED:
        print(f"[OL-MONITOR] Job {event.job_id} completed successfully.", flush=True)
    elif event.code == EVENT_JOB_ERROR:
        print(f"[OL-MONITOR] Job {event.job_id} failed.", flush=True)


# Retained for callers that used the old name; it now has asyncio semantics.
OlBlockingScheduler = OlAsyncIOScheduler


def bash_run(cmd: str, sources: list[str] | None = None, capture_output=False):
    if not sources:
        sources = []

    source_paths = [
        (
            os.path.join("scripts", "monitoring", source)
            if not os.path.isabs(source)
            else source
        )
        for source in sources
    ]
    bash_command = "\n".join(
        (
            'set -e',
            *(f'source "{path}"' for path in source_paths),
            cmd,
        )
    )

    return subprocess.run(
        [
            "bash",
            "-c",
            bash_command,
        ],
        check=True,
        # Mainly for testing:
        capture_output=capture_output,
        text=capture_output if capture_output else None,
    )


def get_service_ip(image_name: str) -> str:
    """Return the IP address of a monitoring service container."""
    container = image_name
    if not container.startswith("openlibrary-"):
        container = f"openlibrary-{container}"
    if not container.endswith("-1"):
        container = f"{container}-1"
    result = subprocess.run(
        ["docker", "inspect", "--format", "{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}", container],
        check=True,
        capture_output=True,
        text=True,
    )
    ip = result.stdout.strip()
    if not ip:
        raise ValueError(f"No IP address found for {container}")
    return ip


def limit_server(allowed_hosts: list[str], scheduler: AsyncIOScheduler):
    """
    Keep a scheduled job only when this host matches an allowed name or prefix.

    A trailing `*` matches a hostname prefix. A short name also matches an FQDN.
    """

    def decorator(func):
        hostname = os.environ.get("HOSTNAME", "")
        short_name = hostname.split(".", 1)[0]

        def matches(pattern: str) -> bool:
            if pattern.endswith("*"):
                prefix = pattern[:-1]
                return hostname.startswith(prefix) or short_name.startswith(prefix)
            return pattern == hostname or pattern == short_name

        if not any(matches(pattern) for pattern in allowed_hosts):
            job = scheduler.get_job(func.__name__)
            if job is not None:
                scheduler.remove_job(func.__name__)
        return func

    return decorator
